    if gate_membership != DEFAULT_GATE_MEMBERSHIP:
        forbid_gate_inference()
    if supersession != DEFAULT_SUPERSESSION:
        _fail("D13", f"supersession inference attempted: {supersession}")
    if primary_label != DEFAULT_PRIMARY_LABEL:
