"""Deterministic serialization. Null, UNKNOWN, UNCLASSIFIED, NONE, false, ABSENT stay distinct."""

from __future__ import annotations

import json
from typing import Any

CANONICAL_JSON_SEPARATORS = (",", ":")


def dumps_canonical(payload: Any) -> str:
    """Byte-stable JSON for contract comparison. No timestamps or UUIDs."""
    return json.dumps(
        payload,
        sort_keys=True,
        separators=CANONICAL_JSON_SEPARATORS,
        ensure_ascii=False,
        allow_nan=False,
    )


def dumps_canonical_bytes(payload: Any) -> bytes:
    return dumps_canonical(payload).encode("utf-8")

"""Deterministic transformation-local IDs. Content-hash survivor IDs are forbidden."""

from __future__ import annotations

from scripts.ops.forensic_structure_schema_v1.exceptions import (
    TransformationContractViolation,
)


def mint_transformation_local_id(
    *,
    kind: str,
    source_order: int,
    sidecar_stable_suffix: str,
    layer2_record_index: int | None = None,
) -> str:
    if not kind or "/" in kind or " " in kind:
        raise TransformationContractViolation("DR-007", f"invalid tlid kind {kind!r}")
    if source_order < 0:
        raise TransformationContractViolation("DR-007", "source_order must be >= 0")
    if not sidecar_stable_suffix:
        raise TransformationContractViolation(
            "DR-007", "sidecar_stable_suffix is required"
        )
    padded = f"{source_order:06d}"
    tlid = f"tlid-{kind}-{padded}-{sidecar_stable_suffix}"
    if layer2_record_index is not None:
        tlid = f"{tlid}-r{layer2_record_index}"
    return tlid

"""Stage A — Immutable Input Verification."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

from scripts.ops.forensic_structure_schema_v1.constants import (
    BOUND_SOURCE_PATH,
    BOUND_SIDECAR_PATH,
    EXPECTED_AUTHORITY,
    EXPECTED_BOM,
    EXPECTED_ENCODING,
    EXPECTED_NEWLINE,
    EXPECTED_SIDECAR_ROLE,
    EXPECTED_SIDECAR_SHA256,
    EXPECTED_SOURCE_BYTES,
    EXPECTED_SOURCE_LINES,
    EXPECTED_SOURCE_SHA256,
    EXPECTED_TRAILING_NEWLINE,
    GENERATOR_ID,
    SCHEMA_ID,
    SCHEMA_VERSION,
)
from scripts.ops.forensic_structure_schema_v1.exceptions import (
    TransformationContractViolation,
)
from scripts.ops.forensic_structure_schema_v1.models import InputWitness
from scripts.ops.forensic_structure_schema_v1.state import PipelineState


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _read_immutable(path: Path) -> bytes:
    if path.is_symlink():
        raise TransformationContractViolation(
            "STAGE_A",
            f"refusing to follow symlink input: {path}",
        )
    return path.read_bytes()


def run_stage_a(state: PipelineState) -> None:
    source_sha = sha256_hex(state.source_bytes)
    sidecar_sha = sha256_hex(state.sidecar_bytes)
    if source_sha != EXPECTED_SOURCE_SHA256:
        raise TransformationContractViolation(
            "SOURCE_SHA_DRIFT",
            f"source sha256 {source_sha} != {EXPECTED_SOURCE_SHA256}",
        )
    if sidecar_sha != EXPECTED_SIDECAR_SHA256:
        raise TransformationContractViolation(
            "SIDECAR_SHA_DRIFT",
            f"sidecar sha256 {sidecar_sha} != {EXPECTED_SIDECAR_SHA256}",
        )
    if len(state.source_bytes) != EXPECTED_SOURCE_BYTES:
        raise TransformationContractViolation(
            "STAGE_A",
            f"source bytes {len(state.source_bytes)} != {EXPECTED_SOURCE_BYTES}",
        )
    newline_count = state.source_bytes.count(b"\n")
    if newline_count != EXPECTED_SOURCE_LINES:
        raise TransformationContractViolation(
            "STAGE_A",
            f"source newline count {newline_count} != {EXPECTED_SOURCE_LINES}",
        )
    if not state.source_bytes.endswith(b"\n"):
        raise TransformationContractViolation("STAGE_A", "expected trailing newline")
    if state.source_bytes.startswith(b"\xef\xbb\xbf"):
        raise TransformationContractViolation("STAGE_A", "BOM must be false")

    sidecar = state.sidecar
    for key, expected in (
        ("schema_id", SCHEMA_ID),
        ("schema_version", SCHEMA_VERSION),
        ("generator_id", GENERATOR_ID),
        ("target_authority", EXPECTED_AUTHORITY),
        ("sidecar_authority", EXPECTED_AUTHORITY),
    ):
        observed = sidecar.get(key)
        if observed != expected:
            raise TransformationContractViolation(
                "SCHEMA_OR_GENERATOR_UNEXPECTED_DRIFT",
                f"{key}={observed!r} expected {expected!r}",
            )
    layer0 = sidecar["layer0_blob"]
    if layer0.get("source_sha256") != EXPECTED_SOURCE_SHA256:
        raise TransformationContractViolation("STAGE_A", "layer0 source_sha256 mismatch")
    if layer0.get("source_bytes") != EXPECTED_SOURCE_BYTES:
        raise TransformationContractViolation("STAGE_A", "layer0 source_bytes mismatch")
    if layer0.get("source_line_count") != EXPECTED_SOURCE_LINES:
        raise TransformationContractViolation(
            "STAGE_A", "layer0 source_line_count mismatch"
        )
    if layer0.get("source_locator_at_observation") != BOUND_SOURCE_PATH:
        raise TransformationContractViolation(
            "STAGE_A",
            "layer0 locator is not the bound Documents path",
        )
    if layer0.get("target_authority") != EXPECTED_AUTHORITY:
        raise TransformationContractViolation("C9", "layer0 target_authority != NONE")
    if layer0.get("sidecar_authority") != EXPECTED_AUTHORITY:
        raise TransformationContractViolation("C9", "layer0 sidecar_authority != NONE")
    if layer0.get("bom") != EXPECTED_BOM:
        raise TransformationContractViolation("STAGE_A", "layer0 bom mismatch")
    if layer0.get("encoding") != EXPECTED_ENCODING:
        raise TransformationContractViolation("STAGE_A", "layer0 encoding mismatch")
    if layer0.get("newline") != EXPECTED_NEWLINE:
        raise TransformationContractViolation("STAGE_A", "layer0 newline mismatch")
    if layer0.get("trailing_newline") != EXPECTED_TRAILING_NEWLINE:
        raise TransformationContractViolation(
            "STAGE_A", "layer0 trailing_newline mismatch"
        )
    if layer0.get("generated_from_immutable_source") is not True:
        raise TransformationContractViolation(
            "STAGE_A", "generated_from_immutable_source must be true"
        )
    sidecar_role = sidecar.get("sidecar_role")
    if sidecar_role != EXPECTED_SIDECAR_ROLE:
        raise TransformationContractViolation(
            "STAGE_A",
            f"sidecar_role={sidecar_role!r} expected {EXPECTED_SIDECAR_ROLE!r}",
        )

    state.witness = InputWitness(
        source_path=str(state.source_path),
        sidecar_path=str(state.sidecar_path),
        source_sha256=source_sha,
        sidecar_sha256=sidecar_sha,
        source_bytes=len(state.source_bytes),
        source_line_count=newline_count,
        schema_id=str(sidecar["schema_id"]),
        schema_version=str(sidecar["schema_version"]),
        generator_id=str(sidecar["generator_id"]),
        target_authority=str(sidecar["target_authority"]),
        sidecar_authority=str(sidecar["sidecar_authority"]),
        sidecar_role=str(sidecar_role),
        source_locator_at_observation=str(layer0["source_locator_at_observation"]),
        bom=bool(layer0["bom"]),
        encoding=str(layer0["encoding"]),
        newline=str(layer0["newline"]),
        trailing_newline=bool(layer0["trailing_newline"]),
        generated_from_immutable_source=True,
    )
    state.stages_completed.append("A_IMMUTABLE_INPUT_VERIFICATION")


def load_inputs(source_path: Path, sidecar_path: Path) -> PipelineState:
    source_bytes = _read_immutable(source_path)
    sidecar_bytes = _read_immutable(sidecar_path)
    try:
        sidecar = json.loads(sidecar_bytes.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise TransformationContractViolation(
            "STAGE_A",
            f"sidecar is not UTF-8 JSON: {exc}",
        ) from exc
    if not isinstance(sidecar, dict):
        raise TransformationContractViolation("STAGE_A", "sidecar root must be an object")
    return PipelineState(
        source_path=source_path,
        sidecar_path=sidecar_path,
        source_bytes=source_bytes,
        sidecar_bytes=sidecar_bytes,
        sidecar=sidecar,
        source_sha256_before=sha256_hex(source_bytes),
        sidecar_sha256_before=sha256_hex(sidecar_bytes),
    )

"""Stage B — Raw Occurrence Registry. Primary key is occurrence_id, never content hash."""

from __future__ import annotations

from scripts.ops.forensic_structure_schema_v1.constants import (
    EXPECTED_LOSSLESSNESS,
    EXPECTED_SOURCE_BYTES,
    LAYER1_FIELD_ORDER,
)
from scripts.ops.forensic_structure_schema_v1.exceptions import (
    TransformationContractViolation,
)
from scripts.ops.forensic_structure_schema_v1.models import Layer1Occurrence
from scripts.ops.forensic_structure_schema_v1.state import PipelineState


def run_stage_b(state: PipelineState) -> None:
    raw = state.sidecar["layer1_raw_spans"]
    field_order = tuple(raw["field_order"])
    if field_order != LAYER1_FIELD_ORDER:
        raise TransformationContractViolation(
            "STAGE_B",
            f"layer1 field_order drift: {field_order}",
        )
    spans_raw = raw["spans"]
    expected_n = EXPECTED_LOSSLESSNESS["LAYER1_COUNT"]
    if len(spans_raw) != expected_n:
        raise TransformationContractViolation(
            "STAGE_B",
            f"layer1 count {len(spans_raw)} != {expected_n}",
        )

    ordered: list[Layer1Occurrence] = []
    by_id: dict[str, Layer1Occurrence] = {}
    prev_end = 0
    for index, tup in enumerate(spans_raw):
        if not isinstance(tup, list) or len(tup) != 8:
            raise TransformationContractViolation(
                "STAGE_B",
                f"layer1 tuple arity drift at index {index}",
            )
        occ = Layer1Occurrence(
            occurrence_id=str(tup[0]),
            source_sequence=int(tup[1]),
            byte_start=int(tup[2]),
            byte_end=int(tup[3]),
            line_start=int(tup[4]),
            line_end=int(tup[5]),
            content_hash_sha256=str(tup[6]),
            mechanical_type=str(tup[7]),
        )
        if occ.occurrence_id in by_id:
            raise TransformationContractViolation(
                "C2",
                f"duplicate layer1 occurrence_id {occ.occurrence_id}",
            )
        if occ.source_sequence != index + 1:
            raise TransformationContractViolation(
                "STAGE_B",
                f"source_sequence drift at {index}: {occ.source_sequence}",
            )
        if occ.byte_start != prev_end:
            raise TransformationContractViolation(
                "STAGE_B",
                f"layer1 gap/overlap at index {index}: prev_end={prev_end} "
                f"byte_start={occ.byte_start}",
            )
        if occ.byte_end < occ.byte_start:
            raise TransformationContractViolation(
                "STAGE_B",
                f"inverted byte range on {occ.occurrence_id}",
            )
        if occ.line_start != occ.line_end or occ.line_start != occ.source_sequence:
            raise TransformationContractViolation(
                "STAGE_B",
                f"layer1 single-line invariant failed on {occ.occurrence_id}",
            )
        by_id[occ.occurrence_id] = occ
        ordered.append(occ)
        prev_end = occ.byte_end

    if ordered[0].byte_start != 0 or prev_end != EXPECTED_SOURCE_BYTES:
        raise TransformationContractViolation(
            "STAGE_B",
            f"layer1 byte union is [{ordered[0].byte_start}, {prev_end}) "
            f"expected [0, {EXPECTED_SOURCE_BYTES})",
        )

    state.layer1_ordered = ordered
    state.layer1_by_id = by_id
    state.stages_completed.append("B_RAW_OCCURRENCE_REGISTRY")

"""Stage C — Overlay Registry. Kind-partitioned; t5_multilabel overlay_kind stays ABSENT."""

from __future__ import annotations

from typing import Any

from scripts.ops.forensic_structure_schema_v1.constants import (
    EXPECTED_LOSSLESSNESS,
    OVERLAY_CLASS_ORDER,
)
from scripts.ops.forensic_structure_schema_v1.exceptions import (
    TransformationContractViolation,
)
from scripts.ops.forensic_structure_schema_v1.id_spaces import (
    assert_token_layer1_disjoint,
    classify_overlay_id,
)
from scripts.ops.forensic_structure_schema_v1.models import OptionalValue, OverlayRecord
from scripts.ops.forensic_structure_schema_v1.state import PipelineState

_LAYER1_REF_FIELDS = (
    "occurrence_id",
    "heading_occurrence_id",
    "open_occurrence_id",
    "close_occurrence_id",
    "begin_occurrence_id",
    "end_occurrence_id",
)

_OVERLAY_REF_FIELDS = (
    "json_fence_overlay_id",
    "wrapper_pair_overlay_id",
)


def _copy_payload(record: dict[str, Any]) -> dict[str, Any]:
    return dict(record)


def run_stage_c(state: PipelineState) -> None:
    overlays_raw = state.sidecar["layer1c_overlays"]
    observed_classes = tuple(overlays_raw.keys())
    if observed_classes != OVERLAY_CLASS_ORDER:
        raise TransformationContractViolation(
            "STAGE_C",
            f"overlay class order drift: {observed_classes}",
        )

    overlays_by_class: dict[str, list[OverlayRecord]] = {}
    overlay_by_id: dict[str, OverlayRecord] = {}
    alias_to_overlay_id: dict[str, str] = {}
    token_occurrence_ids: set[str] = set()
    body_sha_to_ids: dict[str, list[str]] = {}

    for class_name in OVERLAY_CLASS_ORDER:
        records = overlays_raw[class_name]
        if not isinstance(records, list):
            raise TransformationContractViolation(
                "STAGE_C",
                f"{class_name} must be an array",
            )
        class_list: list[OverlayRecord] = []
        for index, raw in enumerate(records):
            if not isinstance(raw, dict):
                raise TransformationContractViolation(
                    "STAGE_C",
                    f"{class_name}[{index}] is not an object",
                )
            overlay_id = str(raw["overlay_id"])
            if overlay_id in overlay_by_id:
                raise TransformationContractViolation(
                    "C2",
                    f"duplicate overlay_id {overlay_id}",
                )
            kind = OptionalValue.from_mapping(raw, "overlay_kind")
            if class_name == "t5_multilabel" and kind.presence != "absent":
                raise TransformationContractViolation(
                    "SW-R-007",
                    "t5_multilabel overlay_kind must remain ABSENT",
                )
            rec = OverlayRecord(
                overlay_id=overlay_id,
                overlay_kind=kind,
                overlay_class=class_name,
                payload=_copy_payload(raw),
                sidecar_index=index,
                byte_start=OptionalValue.from_mapping(raw, "byte_start"),
                byte_end=OptionalValue.from_mapping(raw, "byte_end"),
            )
            classify_overlay_id(overlay_id)
            overlay_by_id[overlay_id] = rec
            class_list.append(rec)
            alias = raw.get("source_identifier_alias")
            if isinstance(alias, str) and alias:
                if alias in alias_to_overlay_id:
                    raise TransformationContractViolation(
                        "STAGE_C",
                        f"duplicate alias {alias} for overlays "
                        f"{alias_to_overlay_id[alias]} and {overlay_id}",
                    )
                alias_to_overlay_id[alias] = overlay_id
            if class_name == "token_occurrence":
                token_occ = str(raw["occurrence_id"])
                if token_occ in token_occurrence_ids:
                    raise TransformationContractViolation(
                        "C2",
                        f"duplicate token occurrence_id {token_occ}",
                    )
                token_occurrence_ids.add(token_occ)
                if raw.get("normalized") is True:
                    raise TransformationContractViolation(
                        "C8",
                        f"token {overlay_id} has normalized=true",
                    )
            if class_name == "fence_block":
                body_sha = str(raw["body_sha256"])
                body_sha_to_ids.setdefault(body_sha, []).append(overlay_id)
            if class_name == "t5_multilabel" and raw.get("collapsed") is True:
                raise TransformationContractViolation(
                    "C4",
                    f"{overlay_id} collapsed=true",
                )
        overlays_by_class[class_name] = class_list

    epochs_raw = state.sidecar["layer1b_append_epochs"]
    epoch_list: list[OverlayRecord] = []
    for index, raw in enumerate(epochs_raw):
        overlay_id = str(raw["overlay_id"])
        if overlay_id in overlay_by_id:
            raise TransformationContractViolation("C2", f"duplicate epoch overlay {overlay_id}")
        rec = OverlayRecord(
            overlay_id=overlay_id,
            overlay_kind=OptionalValue.from_mapping(raw, "overlay_kind"),
            overlay_class="append_epoch",
            payload=_copy_payload(raw),
            sidecar_index=index,
            byte_start=OptionalValue.from_mapping(raw, "byte_start"),
            byte_end=OptionalValue.from_mapping(raw, "byte_end"),
        )
        overlay_by_id[overlay_id] = rec
        epoch_list.append(rec)
        if raw.get("authority_derived") is True:
            raise TransformationContractViolation("C9", f"{overlay_id} authority_derived=true")
        if raw.get("world_time_derived") is True:
            raise TransformationContractViolation("D2", f"{overlay_id} world_time_derived=true")
    overlays_by_class["append_epoch"] = epoch_list

    layer1_ids = set(state.layer1_by_id)
    assert_token_layer1_disjoint(token_occurrence_ids, layer1_ids)

    for rec in overlay_by_id.values():
        payload = rec.payload
        for field_name in _LAYER1_REF_FIELDS:
            if field_name not in payload:
                continue
            value = payload[field_name]
            if value is None:
                continue
            occ = str(value)
            if rec.overlay_class == "token_occurrence" and field_name == "occurrence_id":
                if occ in layer1_ids:
                    raise TransformationContractViolation(
                        "SW-R-008",
                        f"token {rec.overlay_id} occurrence_id equality-joins layer1",
                    )
                continue
            if occ not in layer1_ids:
                raise TransformationContractViolation(
                    "LAYER1_OCCURRENCE_REFERENCE",
                    f"{rec.overlay_id}.{field_name}={occ} not in LAYER1",
                )
        for field_name in _OVERLAY_REF_FIELDS:
            if field_name not in payload:
                continue
            value = payload[field_name]
            if value is None:
                continue
            oid = str(value)
            if oid not in overlay_by_id:
                raise TransformationContractViolation(
                    "OVERLAY_REFERENCE",
                    f"{rec.overlay_id}.{field_name}={oid} unknown overlay",
                )
        if rec.overlay_class == "t5_cls_row":
            aliases = rec.payload.get("cls_aliases")
            if aliases is not None:
                raise TransformationContractViolation(
                    "STAGE_C",
                    "t5_cls_row must not carry cls_aliases",
                )
        if rec.overlay_class == "t5_multilabel":
            aliases = rec.payload.get("cls_aliases") or []
            if len(aliases) != int(rec.payload["row_count"]):
                raise TransformationContractViolation(
                    "C4",
                    f"{rec.overlay_id} row_count != len(cls_aliases)",
                )
            for alias in aliases:
                mapped = alias_to_overlay_id.get(str(alias))
                if mapped is None:
                    raise TransformationContractViolation(
                        "EXPLICIT_ALIAS_MAP_NAVIGATION_ONLY",
                        f"{rec.overlay_id} unknown cls alias {alias}",
                    )

    expected = EXPECTED_LOSSLESSNESS
    _require_count(overlays_by_class, "fence_block", expected["FENCE_BLOCK_COUNT"])
    _require_count(overlays_by_class, "h1_span", expected["H1_SPAN_COUNT"])
    _require_count(overlays_by_class, "t3_src_span", expected["T3_SRC_SPAN_COUNT"])
    _require_count(
        overlays_by_class, "wrapper_mention", expected["WRAPPER_MENTION_COUNT"]
    )
    _require_count(overlays_by_class, "wrapper_pair", expected["WRAPPER_PAIR_COUNT"])
    _require_count(
        overlays_by_class, "t5_multilabel", expected["T5_MULTILABEL_COUNT"]
    )
    _require_count(
        overlays_by_class, "token_occurrence", expected["TOKEN_OCCURRENCE_COUNT"]
    )
    _require_count(overlays_by_class, "t4_rel_row", expected["T4_REL_ROW_COUNT"])
    _require_count(overlays_by_class, "t5_cls_row", expected["T5_CLS_ROW_COUNT"])
    _require_count(overlays_by_class, "kv_packet", expected["KV_PACKET_COUNT"])
    _require_count(
        overlays_by_class, "forensic_record", expected["FORENSIC_RECORD_COUNT"]
    )
    _require_count(overlays_by_class, "append_epoch", expected["APPEND_EPOCH_COUNT"])

    unique_body = len(body_sha_to_ids)
    if unique_body != expected["FENCE_UNIQUE_BODY_HASHES"]:
        raise TransformationContractViolation(
            "C3",
            f"unique fence body hashes {unique_body} != "
            f"{expected['FENCE_UNIQUE_BODY_HASHES']}",
        )
    dup_groups = sum(1 for ids in body_sha_to_ids.values() if len(ids) > 1)
    if dup_groups != expected["FENCE_DUPLICATE_GROUPS"]:
        raise TransformationContractViolation(
            "C3",
            f"duplicate fence groups {dup_groups} != {expected['FENCE_DUPLICATE_GROUPS']}",
        )

    state.overlays_by_class = overlays_by_class
    state.overlay_by_id = overlay_by_id
    state.alias_to_overlay_id = alias_to_overlay_id
    state.token_occurrence_ids = token_occurrence_ids
    state.body_sha_to_overlay_ids = body_sha_to_ids
    state.stages_completed.append("C_OVERLAY_REGISTRY")


def _require_count(
    overlays_by_class: dict[str, list[OverlayRecord]], name: str, expected: int
) -> None:
    observed = len(overlays_by_class[name])
    if observed != expected:
        raise TransformationContractViolation(
            "STAGE_C",
            f"{name} count {observed} != {expected}",
        )

"""Stage D — Provenance Registry. Missing basis is UNKNOWN, never false/STRUCTURAL."""

from __future__ import annotations

from typing import Any

from scripts.ops.forensic_structure_schema_v1.constants import DUAL_CLASS_OCCURRENCE_ID
from scripts.ops.forensic_structure_schema_v1.exceptions import (
    TransformationContractViolation,
)
from scripts.ops.forensic_structure_schema_v1.models import OptionalValue, ProvenanceTag
from scripts.ops.forensic_structure_schema_v1.state import PipelineState

_BASIS_TO_PROVENANCE = {
    "FACT_FROM_SOURCE": "FACT_FROM_SOURCE",
    "STRUCTURAL_DERIVATION": "STRUCTURAL_DERIVATION",
    "STRUCTURAL_INFERENCE": "STRUCTURAL_DERIVATION",
    "PRIOR_ADJUDICATION_REFERENCE": "PRIOR_ADJUDICATION_REFERENCE",
    "EXPLICIT_TEXT": "EXPLICIT_TEXT_RELATION",
    "EXPLICIT_TEXT_RELATION": "EXPLICIT_TEXT_RELATION",
}


def _provenance_from_basis(basis: Any) -> str:
    if basis is None:
        return "UNKNOWN"
    mapped = _BASIS_TO_PROVENANCE.get(str(basis))
    if mapped is None:
        return "UNKNOWN"
    return mapped


def run_stage_d(state: PipelineState) -> None:
    tags: list[ProvenanceTag] = []
    layer2 = state.sidecar["layer2_classification"]["records"]
    dual_count = 0
    for index, raw in enumerate(layer2):
        occ = str(raw["occurrence_id"])
        if occ not in state.layer1_by_id:
            raise TransformationContractViolation(
                "LAYER1_OCCURRENCE_REFERENCE",
                f"layer2[{index}] occurrence_id {occ} not in LAYER1",
            )
        overlay_ref = raw.get("overlay_ref")
        if overlay_ref is not None and str(overlay_ref) not in state.overlay_by_id:
            raise TransformationContractViolation(
                "OVERLAY_REFERENCE",
                f"layer2[{index}] overlay_ref {overlay_ref} unknown",
            )
        if occ == DUAL_CLASS_OCCURRENCE_ID:
            dual_count += 1
        basis = OptionalValue.from_mapping(raw, "epistemic_basis")
        tags.append(
            ProvenanceTag(
                subject_kind="layer2_record",
                subject_id=f"layer2-{index}-{occ}",
                provenance_type=_provenance_from_basis(raw.get("epistemic_basis")),
                epistemic_basis=basis,
                sidecar_index=index,
            )
        )
    if dual_count != 2:
        raise TransformationContractViolation(
            "SW-R-011",
            f"dual-class occurrence must have 2 layer2 records, found {dual_count}",
        )

    overlay_with_layer2 = {
        str(raw["overlay_ref"])
        for raw in layer2
        if raw.get("overlay_ref") is not None
    }
    for overlay_id, rec in state.overlay_by_id.items():
        if overlay_id in overlay_with_layer2:
            continue
        payload = rec.payload
        basis_val = payload.get("epistemic_basis")
        if rec.overlay_class == "token_occurrence":
            ptype = "FACT_FROM_SOURCE"
        elif rec.overlay_class in {
            "fence_block",
            "h1_span",
            "kv_packet",
            "wrapper_mention",
            "wrapper_pair",
            "append_epoch",
            "t5_multilabel",
        }:
            ptype = "STRUCTURAL_DERIVATION"
        elif rec.overlay_class in {
            "t3_src_span",
            "t4_rel_row",
            "t5_cls_row",
            "forensic_record",
        }:
            ptype = "PRIOR_ADJUDICATION_REFERENCE"
        else:
            ptype = _provenance_from_basis(basis_val)
        tags.append(
            ProvenanceTag(
                subject_kind="overlay",
                subject_id=overlay_id,
                provenance_type=ptype,
                epistemic_basis=OptionalValue.from_mapping(payload, "epistemic_basis"),
                sidecar_index=rec.sidecar_index,
            )
        )

    state.provenance = tags
    state.stages_completed.append("D_PROVENANCE_REGISTRY")

"""Stage F — Semantic Envelope Projection. Incomplete positive semantics are legal."""

from __future__ import annotations

from typing import Any

from scripts.ops.forensic_structure_schema_v1.constants import (
    DEFAULT_EPISTEMIC_CLASS,
    DUAL_CLASS_OCCURRENCE_ID,
    EXPECTED_SOURCE_SHA256,
    OVERLAY_CLASS_ORDER,
)
from scripts.ops.forensic_structure_schema_v1.exceptions import (
    TransformationContractViolation,
)
from scripts.ops.forensic_structure_schema_v1.joins import byte_range_containing_span
from scripts.ops.forensic_structure_schema_v1.minting import mint_transformation_local_id
from scripts.ops.forensic_structure_schema_v1.models import OptionalValue, SemanticEnvelope
from scripts.ops.forensic_structure_schema_v1.state import PipelineState

_CLASS_SOURCE_ORDER_BASE = {
    "append_epoch": 0,
    "fence_block": 100_000,
    "forensic_record": 200_000,
    "h1_span": 300_000,
    "kv_packet": 400_000,
    "t3_src_span": 500_000,
    "t4_rel_row": 600_000,
    "t5_cls_row": 700_000,
    "t5_multilabel": 800_000,
    "token_occurrence": 900_000,
    "wrapper_mention": 1_000_000,
    "wrapper_pair": 1_100_000,
    "layer2": 2_000_000,
}


def _int_optional(record: dict[str, Any], key: str) -> OptionalValue:
    return OptionalValue.from_mapping(record, key)


def _byte_bounds(payload: dict[str, Any], state: PipelineState) -> tuple[int, int]:
    if "byte_start" in payload and "byte_end" in payload:
        start = int(payload["byte_start"])
        end = int(payload["byte_end"])
        if start < 0 or end > len(state.source_bytes) or end < start:
            raise TransformationContractViolation(
                "C1",
                f"byte range [{start}, {end}) outside source blob",
            )
        return start, end
    raise TransformationContractViolation(
        "C1",
        "envelope requires byte bind or documentary relation; byte range absent",
    )


def _layer1_for_overlay(
    rec_class: str, payload: dict[str, Any], state: PipelineState
) -> OptionalValue:
    if rec_class == "token_occurrence":
        span = byte_range_containing_span(
            state.layer1_ordered,
            int(payload["byte_start"]),
            int(payload["byte_end"]),
            line=int(payload["line"]) if "line" in payload else None,
        )
        token_occ = str(payload["occurrence_id"])
        if token_occ == span.occurrence_id:
            raise TransformationContractViolation(
                "SW-R-008",
                "token occurrence_id copied into layer1_occurrence_id",
            )
        return OptionalValue.present(span.occurrence_id)
    for field_name in (
        "heading_occurrence_id",
        "open_occurrence_id",
        "begin_occurrence_id",
        "occurrence_id",
    ):
        if field_name in payload and payload[field_name] is not None:
            if rec_class == "token_occurrence":
                continue
            occ = str(payload[field_name])
            if occ not in state.layer1_by_id:
                raise TransformationContractViolation(
                    "LAYER1_OCCURRENCE_REFERENCE",
                    f"unknown layer1 id {occ}",
                )
            return OptionalValue.present(occ)
    if rec_class == "kv_packet":
        span = byte_range_containing_span(
            state.layer1_ordered,
            int(payload["byte_start"]),
            int(payload["byte_end"]),
        )
        return OptionalValue.present(span.occurrence_id)
    if rec_class in {"t5_multilabel", "append_epoch"}:
        return OptionalValue.null()
    if "byte_start" in payload and "byte_end" in payload:
        start = int(payload["byte_start"])
        end = int(payload["byte_end"])
        if end - start <= 0:
            return OptionalValue.null()
        try:
            span = byte_range_containing_span(state.layer1_ordered, start, min(end, start + 1))
            return OptionalValue.present(span.occurrence_id)
        except TransformationContractViolation:
            return OptionalValue.null()
    return OptionalValue.null()


def _residuals_for_class(rec_class: str, payload: dict[str, Any]) -> list[str]:
    residuals: list[str] = ["SW-R-001", "SW-R-012"]
    if rec_class == "t4_rel_row":
        residuals.append("SW-R-002")
    if rec_class == "t5_cls_row" and payload.get("classified_source_line") is None:
        residuals.append("SW-R-003")
    if rec_class == "h1_span":
        residuals.extend(["SW-R-005", "SW-R-011"] if payload.get("heading_occurrence_id") == DUAL_CLASS_OCCURRENCE_ID else ["SW-R-005"])
    if rec_class == "fence_block" and payload.get("inner_shorter_fence_like") is True:
        residuals.append("SW-R-006")
    if rec_class == "t5_multilabel":
        residuals.extend(["SW-R-007", "SW-R-013"])
    if rec_class == "token_occurrence":
        residuals.extend(["SW-R-008", "DR-001"])
    if rec_class == "append_epoch":
        residuals.append("SW-R-010")
    if rec_class == "t3_src_span":
        residuals.append("SW-R-015")
    if rec_class == "forensic_record" and payload.get("binds_blob_sha256") is None:
        residuals.append("SW-R-014")
    if rec_class == "kv_packet":
        residuals.append("DR-008")
    residuals.append("DR-006")
    residuals.append("DR-007")
    return sorted(set(residuals))


def _provenance_for_overlay(rec_class: str) -> str:
    if rec_class == "token_occurrence":
        return "FACT_FROM_SOURCE"
    if rec_class in {
        "t3_src_span",
        "t4_rel_row",
        "t5_cls_row",
        "forensic_record",
    }:
        return "PRIOR_ADJUDICATION_REFERENCE"
    return "STRUCTURAL_DERIVATION"


def run_stage_f(state: PipelineState) -> None:
    if state.guards is None:
        raise TransformationContractViolation("STAGE_F", "GuardProgram missing")
    envelopes: list[SemanticEnvelope] = []
    by_overlay: dict[str, list[SemanticEnvelope]] = {}
    by_tlid: dict[str, SemanticEnvelope] = {}

    class_iter = ("append_epoch",) + OVERLAY_CLASS_ORDER
    for rec_class in class_iter:
        for rec in state.overlays_by_class[rec_class]:
            payload = rec.payload
            if rec_class == "t5_multilabel":
                cls_aliases = payload.get("cls_aliases") or []
                first_cls = state.alias_to_overlay_id[str(cls_aliases[0])]
                first_payload = state.overlay_by_id[first_cls].payload
                start, end = _byte_bounds(first_payload, state)
            else:
                start, end = _byte_bounds(payload, state)
            source_order = _CLASS_SOURCE_ORDER_BASE[rec_class] + rec.sidecar_index
            tlid = mint_transformation_local_id(
                kind=rec_class,
                source_order=source_order,
                sidecar_stable_suffix=rec.overlay_id,
            )
            currentness = "CURRENTNESS_UNKNOWN"
            temporal = OptionalValue.from_mapping(payload, "temporal_status")
            if temporal.presence == "present" and temporal.value == "currentness_unknown":
                currentness = "CURRENTNESS_UNKNOWN"
            envelope = SemanticEnvelope(
                transformation_local_id=tlid,
                source_byte_start=start,
                source_byte_end=end,
                source_sha256=EXPECTED_SOURCE_SHA256,
                sidecar_overlay_id=OptionalValue.present(rec.overlay_id),
                layer1_occurrence_id=_layer1_for_overlay(rec_class, payload, state),
                token_occurrence_id=(
                    OptionalValue.present(str(payload["occurrence_id"]))
                    if rec_class == "token_occurrence"
                    else OptionalValue.null()
                ),
                provenance_type=_provenance_for_overlay(rec_class),
                unresolved_status=OptionalValue.from_mapping(payload, "unresolved"),
                source_order=source_order,
                content_class=str(
                    payload.get("content_class_mapped")
                    or payload.get("content_class")
                    or DEFAULT_EPISTEMIC_CLASS
                ),
                t5_label_verbatim=OptionalValue.from_mapping(payload, "t5_label_verbatim"),
                hash_kind=OptionalValue.from_mapping(payload, "hash_kind"),
                classified_source_line=OptionalValue.from_mapping(
                    payload, "classified_source_line"
                ),
                binds_blob_sha256=OptionalValue.from_mapping(payload, "binds_blob_sha256"),
                binds_blob_sha256_matches_current=OptionalValue.from_mapping(
                    payload, "binds_blob_sha256_matches_current"
                ),
                currentness_upgrade=OptionalValue.from_mapping(
                    payload, "currentness_upgrade"
                ),
                temporal_status=temporal,
                overlay_kind=rec.overlay_kind,
                overlay_class=rec_class,
                token_class=OptionalValue.from_mapping(payload, "token_class"),
                token_verbatim=OptionalValue.from_mapping(payload, "token_verbatim"),
                normalized=OptionalValue.from_mapping(payload, "normalized"),
                locator_role=OptionalValue.from_mapping(payload, "locator_role"),
                collapsed=OptionalValue.from_mapping(payload, "collapsed"),
                instance_vs_mention=OptionalValue.from_mapping(
                    payload, "instance_vs_mention"
                ),
                is_dependency=OptionalValue.from_mapping(payload, "is_dependency"),
                residuals=_residuals_for_class(rec_class, payload),
                currentness_status=currentness,
            )
            if rec_class == "token_occurrence":
                if envelope.hash_kind.presence == "present":
                    if envelope.hash_kind.value != "UNKNOWN":
                        raise TransformationContractViolation(
                            "D7",
                            f"{rec.overlay_id} hash_kind={envelope.hash_kind.value}",
                        )
                if envelope.currentness_upgrade.presence == "present":
                    if envelope.currentness_upgrade.value is not False:
                        raise TransformationContractViolation(
                            "D8",
                            f"{rec.overlay_id} currentness_upgrade is not false",
                        )
                if envelope.locator_role.presence == "present":
                    if envelope.locator_role.value != "HISTORICAL_STRING":
                        raise TransformationContractViolation(
                            "C7",
                            f"{rec.overlay_id} locator_role mutated",
                        )
            if rec_class == "h1_span":
                envelope.semantic_container = "NOT_ADJUDICATED"
                envelope.content_class = "UNCLASSIFIED"
            if rec_class == "t5_cls_row" and payload.get("authority_status") not in {
                None,
                "NONE",
            }:
                raise TransformationContractViolation(
                    "C9",
                    f"{rec.overlay_id} authority_status != NONE",
                )
            state.guards.check_envelope_defaults(envelope)
            envelopes.append(envelope)
            by_overlay.setdefault(rec.overlay_id, []).append(envelope)
            by_tlid[tlid] = envelope

    layer2_by_occ: dict[str, list[SemanticEnvelope]] = {}
    layer2_records = state.sidecar["layer2_classification"]["records"]
    for index, raw in enumerate(layer2_records):
        occ = str(raw["occurrence_id"])
        span = state.layer1_by_id[occ]
        overlay_ref = OptionalValue.from_mapping(raw, "overlay_ref")
        suffix = (
            str(overlay_ref.value)
            if overlay_ref.presence == "present"
            else occ
        )
        tlid = mint_transformation_local_id(
            kind="layer2",
            source_order=_CLASS_SOURCE_ORDER_BASE["layer2"] + index,
            sidecar_stable_suffix=suffix,
            layer2_record_index=index if occ == DUAL_CLASS_OCCURRENCE_ID else None,
        )
        temporal = OptionalValue.from_mapping(raw, "temporal_status")
        currentness = "CURRENTNESS_UNKNOWN"
        if temporal.presence == "present" and temporal.value == "historical":
            currentness = "historical"
        envelope = SemanticEnvelope(
            transformation_local_id=tlid,
            source_byte_start=span.byte_start,
            source_byte_end=span.byte_end,
            source_sha256=EXPECTED_SOURCE_SHA256,
            sidecar_overlay_id=overlay_ref,
            layer1_occurrence_id=OptionalValue.present(occ),
            token_occurrence_id=OptionalValue.null(),
            provenance_type=(
                "PRIOR_ADJUDICATION_REFERENCE"
                if raw.get("epistemic_basis") == "PRIOR_ADJUDICATION_REFERENCE"
                else (
                    "EXPLICIT_TEXT_RELATION"
                    if raw.get("epistemic_basis") == "EXPLICIT_TEXT"
                    else "STRUCTURAL_DERIVATION"
                    if raw.get("epistemic_basis") == "STRUCTURAL_INFERENCE"
                    else "UNKNOWN"
                )
            ),
            unresolved_status=OptionalValue.from_mapping(raw, "unresolved"),
            source_order=_CLASS_SOURCE_ORDER_BASE["layer2"] + index,
            content_class=str(raw.get("content_class") or DEFAULT_EPISTEMIC_CLASS),
            t5_label_verbatim=OptionalValue.from_mapping(raw, "t5_label_verbatim"),
            classified_source_line=_int_optional(raw, "classified_source_line"),
            binds_blob_sha256=OptionalValue.from_mapping(raw, "binds_blob_sha256"),
            temporal_status=temporal,
            overlay_class="layer2",
            residuals=["SW-R-011", "SW-R-012", "DR-006", "DR-007"]
            if occ == DUAL_CLASS_OCCURRENCE_ID
            else ["SW-R-012", "DR-006", "DR-007"],
            currentness_status=currentness,
        )
        if raw.get("authority_status") != "NONE":
            raise TransformationContractViolation(
                "C9",
                f"layer2[{index}] authority_status != NONE",
            )
        state.guards.check_envelope_defaults(envelope)
        envelopes.append(envelope)
        layer2_by_occ.setdefault(occ, []).append(envelope)
        by_tlid[tlid] = envelope
        if overlay_ref.presence == "present":
            by_overlay.setdefault(str(overlay_ref.value), []).append(envelope)

    dual = layer2_by_occ.get(DUAL_CLASS_OCCURRENCE_ID, [])
    if len(dual) != 2:
        raise TransformationContractViolation(
            "SW-R-011",
            f"dual-class envelopes {len(dual)} != 2",
        )
    if dual[0].transformation_local_id == dual[1].transformation_local_id:
        raise TransformationContractViolation(
            "SW-R-011",
            "dual-class envelopes collapsed to one transformation_local_id",
        )

    state.envelopes = envelopes
    state.envelope_by_overlay_id = by_overlay
    state.envelope_by_tlid = by_tlid
    state.layer2_envelopes_by_occurrence = layer2_by_occ
    state.stages_completed.append("F_SEMANTIC_ENVELOPE_PROJECTION")

